<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {Image,RefreshCw,Download,X,LoaderCircle,Maximize2,AlertCircle,MousePointer2,ExternalLink} from 'lucide-vue-next';
import BiLiveViewer from './BiLiveViewer.vue';
import {appUrl} from '../lib/urls';
import {choosePreview,dashboardPreviews,projectPreviews} from '../lib/project-previews';
type Item=Record<string,any>;
const props=defineProps<{project:Item;artifacts:Item[];request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{close:[];inspect:[artifact:Item];generated:[artifact:Item]}>();
const mode=ref<'interactive'|'image'>('interactive');const interactiveAvailable=ref(false);const nativeUrl=ref('');const liveVersion=ref(0);const requestedDashboard=ref<string|null>(new URLSearchParams(window.location.search).get('dashboard'));
function openInteractive(id?:string|null){mode.value='interactive';if(id){requestedDashboard.value=id;if(dashboards.value.some(item=>String(item.id)===id)){dashboard.value=id;choseDashboard.value=true;}}liveVersion.value++;}
defineExpose({openInteractive});
const sourceAvailable=computed(()=>/^app:[1-9][0-9]*$/.test(props.project.source_ref??''));
const allChoices=computed(()=>projectPreviews(props.artifacts,props.project.id,props.project.source_ref));
const dashboards=ref<Item[]>([]);const dashboard=ref('');const contextLoading=ref(false);const contextError=ref('');const contextReady=ref(false);const listAvailable=ref(true);const choseDashboard=ref(false);
const choices=computed(()=>dashboardPreviews(allChoices.value,dashboard.value||null,dashboards.value[0]?.id?String(dashboards.value[0].id):null));
const follow=ref(true);const selectedId=ref<string|null>(null);const selected=computed(()=>choosePreview(choices.value,selectedId.value,follow.value));
const canRender=computed(()=>sourceAvailable.value&&contextReady.value&&!contextLoading.value&&(dashboards.value.length>0||!listAvailable.value));
const image=ref('');const loading=ref(false);const rendering=ref(false);const error=ref('');let version=0;let contextVersion=0;let disposed=false;
function date(value:string){const time=new Date(value);return Number.isNaN(time.getTime())?'Data não informada':time.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});}
function clear(){if(image.value)URL.revokeObjectURL(image.value);image.value='';}
async function loadContext(){const current=++contextVersion;contextError.value='';if(!sourceAvailable.value){contextReady.value=false;contextLoading.value=false;return;}contextLoading.value=true;try{const result=await props.request(`/projects/${props.project.id}/preview-context`);if(current!==contextVersion)return;if(!Array.isArray(result.dashboards))throw new Error('A lista de dashboards não retornou um formato reconhecido.');dashboards.value=result.dashboards;interactiveAvailable.value=result.interactive_available===true;nativeUrl.value=result.native_app_url??'';if(!interactiveAvailable.value)mode.value='image';if(requestedDashboard.value&&dashboards.value.some(item=>String(item.id)===requestedDashboard.value)){dashboard.value=requestedDashboard.value;choseDashboard.value=true;}listAvailable.value=result.dashboards_available!==false;const latest=String(allChoices.value[0]?.metadata?.dashboard_id??'');if(!(choseDashboard.value&&dashboards.value.some(item=>String(item.id)===dashboard.value)))dashboard.value=dashboards.value.some(item=>String(item.id)===latest)?latest:String(dashboards.value[0]?.id??'');contextReady.value=true;}catch(e){if(current===contextVersion){contextReady.value=false;contextError.value=(e as Error).message;}}finally{if(current===contextVersion)contextLoading.value=false;}}
async function load(){const current=++version;clear();error.value='';if(mode.value!=='image'||!selected.value){loading.value=false;return;}const artifact=selected.value;loading.value=true;try{const response=await fetch(appUrl('/api/artifacts/'+encodeURIComponent(artifact.id)+'/download'),{credentials:'same-origin'});if(response.status===401){window.location.assign(appUrl('/login'));return;}if(!response.ok)throw new Error('Não foi possível abrir esta prévia. Confira sua sessão e tente novamente.');const blob=await response.blob();if(blob.type!=='image/png')throw new Error('O arquivo não retornou uma prévia PNG válida.');if(current===version)image.value=URL.createObjectURL(blob);}catch(e){if(current===version)error.value=(e as Error).message;}finally{if(current===version)loading.value=false;}}
async function generate(){if(!canRender.value||rendering.value)return;rendering.value=true;error.value='';try{const result=await props.request(`/projects/${props.project.id}/preview`,'POST',dashboard.value?{dashboard:Number(dashboard.value)}:{});if(disposed)return;follow.value=true;emit('generated',result.artifact);}catch(e){if(!disposed)error.value=(e as Error).message;}finally{rendering.value=false;}}
function toggleFollow(event:Event){const enabled=(event.target as HTMLInputElement).checked;if(!enabled)selectedId.value=selected.value?.id??null;follow.value=enabled;}
function select(event:Event){selectedId.value=(event.target as HTMLSelectElement).value;choseDashboard.value=true;follow.value=false;}
function selectDashboard(event:Event){dashboard.value=(event.target as HTMLSelectElement).value;choseDashboard.value=true;selectedId.value=null;follow.value=true;}
watch([()=>selected.value?.id,()=>mode.value],load,{immediate:true});
watch([()=>props.project.id,()=>props.project.source_ref],()=>{nativeUrl.value='';interactiveAvailable.value=false;dashboards.value=[];dashboard.value='';choseDashboard.value=false;loadContext();},{immediate:true});
watch(()=>allChoices.value[0]?.id,()=>{if(follow.value&&mode.value==='interactive')liveVersion.value++;const latest=String(allChoices.value[0]?.metadata?.dashboard_id??'');if(!latest||!sourceAvailable.value)return;if(!dashboards.value.some(item=>String(item.id)===latest)){loadContext();return;}if(!choseDashboard.value&&follow.value)dashboard.value=latest;});
onUnmounted(()=>{disposed=true;version++;contextVersion++;clear();});
</script>
<template>
 <aside class="project-preview-pane" :class="{'is-interactive':mode==='interactive'}" aria-label="Acompanhamento visual do dashboard"><header><div><Image :size="17"/><strong>Prévia do dashboard</strong></div><button class="icon-button" aria-label="Fechar acompanhamento visual" @click="emit('close')"><X :size="17"/></button></header><div class="project-preview-modes" role="group" aria-label="Tipo de prévia"><button type="button" :aria-pressed="mode==='interactive'" :disabled="!interactiveAvailable||!contextReady" @click="mode='interactive'"><MousePointer2 :size="15"/>Interativa</button><button type="button" :aria-pressed="mode==='image'" @click="mode='image'"><Image :size="15"/>Imagem</button><a v-if="nativeUrl" :href="nativeUrl" target="_blank" rel="noopener noreferrer"><ExternalLink :size="14"/>Abrir no BI</a></div><div class="project-preview-controls"><label class="preview-follow"><input :checked="follow" type="checkbox" @change="toggleFollow"> Acompanhar alterações</label><button v-if="mode==='image'" class="secondary-button" :disabled="rendering||!canRender" @click="generate"><LoaderCircle v-if="rendering" :size="14" class="spin"/><RefreshCw v-else :size="14"/>{{rendering?'Gerando no BI…':'Atualizar imagem'}}</button></div>
  <div v-if="sourceAvailable" class="project-preview-dashboard"><label v-if="dashboards.length">Dashboard<select :value="dashboard" aria-label="Dashboard da prévia" :disabled="contextLoading||rendering" @change="selectDashboard"><option v-for="item in dashboards" :key="item.id" :value="String(item.id)">{{item.name}}</option></select></label><span v-else class="resource-note">{{contextLoading?'Consultando dashboards…':contextReady?(listAvailable?'Nenhum dashboard disponível nesta consulta.':'A lista de dashboards não foi fornecida; a prévia principal pode ser gerada.'):'Escolha de dashboard indisponível.'}}</span><button class="icon-button" aria-label="Atualizar lista de dashboards" :disabled="contextLoading" @click="loadContext"><RefreshCw :size="14" :class="{spin:contextLoading}"/></button></div>
  <p v-if="contextError" class="form-error" role="alert">{{contextError}}</p><p class="project-preview-caption">{{mode==='interactive'?'Explore filtros e gráficos na versão atual do BI. Ao receber uma nova prévia, o painel é recarregado se o acompanhamento estiver ativo.':'A imagem registra uma versão renderizada. Você pode ampliá-la ou baixá-la quando precisar.'}}</p><BiLiveViewer v-if="mode==='interactive'&&interactiveAvailable&&contextReady" :key="project.source_ref+':'+dashboard+':'+liveVersion" :tenant="String(project.tenant_id)" :app-id="project.source_ref.slice(4)" :dashboard="dashboard||undefined" :request="request" @fallback="mode='image'"/><template v-if="mode==='image'">
  <select v-if="choices.length>1" :value="selected?.id" aria-label="Versão da prévia" @change="select"><option v-for="artifact in choices" :key="artifact.id" :value="artifact.id">{{date(artifact.metadata?.generated_at??artifact.created_at)}}</option></select><button v-if="selected&&choices[0]?.id!==selected.id" class="preview-latest" @click="follow=true">Ver a prévia mais recente</button>
  <div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}<button v-if="selected" class="text-button" @click="load">Tentar abrir novamente</button></div><div v-if="loading" class="project-preview-loading" role="status"><LoaderCircle :size="22" class="spin"/>Carregando prévia…</div>
  <div v-else-if="image&&selected" class="project-preview-canvas"><button class="project-preview-enlarge" aria-label="Ampliar imagem do dashboard" @click="emit('inspect',selected)"><img :src="image" :alt="'Prévia real de '+project.name"></button></div>
  <div v-else-if="!selected&&!loading" class="project-preview-empty"><Image :size="34"/><h3>Acompanhe o dashboard aqui</h3><p>{{sourceAvailable?'Gere uma prévia do dashboard selecionado ou peça à IA uma prévia após as alterações.':'A primeira prévia aparecerá quando uma aplicação for criada e renderizada neste projeto.'}}</p></div>
  <footer v-if="selected"><span>Gerada em {{date(selected.metadata?.generated_at??selected.created_at)}} · Brasília</span><div><button class="secondary-button" :disabled="!image" @click="emit('inspect',selected)"><Maximize2 :size="14"/> Ampliar</button><a class="secondary-button" :href="appUrl('/api/artifacts/'+selected.id+'/download')"><Download :size="14"/> Baixar</a></div><p>Para solicitar análise visual com IA, abra a imagem e autorize o envio para a conversa.</p></footer></template>
 </aside>
</template>

<style scoped>
.project-preview-modes{display:flex;align-items:center;gap:5px;padding:12px 16px 0;flex-wrap:wrap}.project-preview-modes button,.project-preview-modes a{display:inline-flex;align-items:center;gap:6px;min-height:34px;padding:7px 10px;border:1px solid transparent;border-radius:7px;font-size:11px;color:#657c9e;background:transparent;text-decoration:none}.project-preview-modes button[aria-pressed="true"]{color:#0b5edb;background:#eaf2ff;border-color:#cbdffb}.project-preview-modes button:disabled{opacity:.5;cursor:default}.project-preview-modes a{margin-left:auto}.project-preview-modes button:focus-visible,.project-preview-modes a:focus-visible{outline:2px solid #0861ee;outline-offset:2px}.project-preview-pane>.bi-live-viewer{margin:0 12px 14px;flex:1;min-height:440px}.project-preview-pane :deep(.bi-live-viewer iframe){min-height:520px;height:60vh}.project-preview-pane :deep(.bi-live-viewer header){flex-wrap:wrap;gap:9px}@media(max-width:760px){.project-preview-pane.is-interactive{max-height:60vh}.project-preview-pane :deep(.bi-live-viewer iframe){min-height:420px;height:52vh}.project-preview-modes{padding:8px 12px 0}}
</style>
